import { ViewTransition, startTransition, useState } from "react";

function ExpandablePreview() {
  const [show, setShow] = useState(false);
  function toggle() {
    startTransition(() => setShow(value => !value));
  }
  return (
    <>
      <button onClick={toggle}>{show ? "Hide preview" : "Show preview"}</button>
      {show && <ViewTransition><section><h2>Preview</h2><p>New content enters with a transition.</p></section></ViewTransition>}
    </>
  );
}
